import React, { useState } from 'react';

interface CounterProps {
  initialValue?: number;
  min?: number;
  max?: number;
}

const Counter: React.FC<CounterProps> = ({
  initialValue = 0,
  min = -Infinity,
  max = Infinity,
}) => {
  const [count, setCount] = useState<number>(initialValue);

  const increment = (): void => {
    setCount((prev) => Math.min(prev + 1, max));
  };

  const decrement = (): void => {
    setCount((prev) => Math.max(prev - 1, min));
  };

  const reset = (): void => {
    setCount(initialValue);
  };

  return (
    <div className="counter" role="group" aria-label="counter controls">
      <h2>Count: {count}</h2>
      <button onClick={increment} aria-label="increment">+</button>
      <button onClick={decrement} aria-label="decrement">-</button>
      <button onClick={reset} aria-label="reset">Reset</button>
    </div>
  );
};

export default Counter;

import React, { useState, useCallback } from 'react';

interface FormErrors {
  email?: string;
  password?: string;
}

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const LoginForm: React.FC = () => {
  const [email, setEmail] = useState<string>('');
  const [password, setPassword] = useState<string>('');
  const [errors, setErrors] = useState<FormErrors>({});
  const [submitting, setSubmitting] = useState<boolean>(false);

  const validate = useCallback((): boolean => {
    const e: FormErrors = {};
    if (!EMAIL_REGEX.test(email)) e.email = 'Invalid email format';
    if (password.length < 8) e.password = 'Password must be at least 8 characters';
    setErrors(e);
    return Object.keys(e).length === 0;
  }, [email, password]);

  const handleSubmit = async (e: React.FormEvent): Promise<void> => {
    e.preventDefault();
    if (!validate() || submitting) return;
    setSubmitting(true);
    try {
      // API call would go here
      await new Promise((r) => setTimeout(r, 500));
    } catch {
      setErrors({ email: 'Login failed. Please try again.' });
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} noValidate aria-label="login form">
      <div>
        <label htmlFor="email">Email</label>
        <input
          id="email" type="email" value={email}
          onChange={(e) => setEmail(e.target.value)}
          aria-invalid={!!errors.email}
          aria-describedby={errors.email ? 'email-error' : undefined}
        />
        {errors.email && <span id="email-error" role="alert">{errors.email}</span>}
      </div>
      <div>
        <label htmlFor="password">Password</label>
        <input
          id="password" type="password" value={password}
          onChange={(e) => setPassword(e.target.value)}
          aria-invalid={!!errors.password}
          aria-describedby={errors.password ? 'password-error' : undefined}
        />
        {errors.password && <span id="password-error" role="alert">{errors.password}</span>}
      </div>
      <button type="submit" disabled={submitting}>
        {submitting ? 'Signing in...' : 'Sign In'}
      </button>
    </form>
  );
};

export default LoginForm;

import { useState, useEffect, useRef } from 'react';

interface FetchState<T> {
  data: T | null;
  loading: boolean;
  error: string | null;
}

function useFetch<T = unknown>(url: string, options?: RequestInit): FetchState<T> {
  const [state, setState] = useState<FetchState<T>>({
    data: null, loading: true, error: null,
  });
  const abortRef = useRef<AbortController | null>(null);

  useEffect(() => {
    const controller = new AbortController();
    abortRef.current = controller;

    const fetchData = async (): Promise<void> => {
      setState((prev) => ({ ...prev, loading: true, error: null }));
      try {
        const res = await fetch(url, { ...options, signal: controller.signal });
        if (!res.ok) throw new Error(`HTTP ${res.status}: ${res.statusText}`);
        const data = (await res.json()) as T;
        if (!controller.signal.aborted) {
          setState({ data, loading: false, error: null });
        }
      } catch (err) {
        if (controller.signal.aborted) return;
        const message = err instanceof Error ? err.message : 'Unknown error';
        setState({ data: null, loading: false, error: message });
      }
    };

    fetchData();
    return () => controller.abort();
  }, [url]);

  return state;
}

export { useFetch };

import React, { useReducer, useState } from 'react';

type Filter = 'all' | 'active' | 'completed';

interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

type Action =
  | { type: 'ADD'; text: string }
  | { type: 'TOGGLE'; id: number }
  | { type: 'DELETE'; id: number };

function todoReducer(state: Todo[], action: Action): Todo[] {
  switch (action.type) {
    case 'ADD':
      return [...state, { id: Date.now(), text: action.text, completed: false }];
    case 'TOGGLE':
      return state.map((t) => t.id === action.id ? { ...t, completed: !t.completed } : t);
    case 'DELETE':
      return state.filter((t) => t.id !== action.id);
    default:
      return state;
  }
}

const TodoApp: React.FC = () => {
  const [todos, dispatch] = useReducer(todoReducer, []);
  const [text, setText] = useState('');
  const [filter, setFilter] = useState<Filter>('all');

  const addTodo = (): void => {
    if (text.trim()) { dispatch({ type: 'ADD', text: text.trim() }); setText(''); }
  };

  const filtered = todos.filter((t) => filter === 'all' ? true : filter === 'active' ? !t.completed : t.completed);

  return (
    <div>
      <input value={text} onChange={(e) => setText(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && addTodo()} />
      <button onClick={addTodo}>Add</button>
      <div>
        <button onClick={() => setFilter('all')}>All</button>
        <button onClick={() => setFilter('active')}>Active</button>
        <button onClick={() => setFilter('completed')}>Completed</button>
      </div>
      <ul>
        {filtered.map((t) => (
          <li key={t.id}>
            <input type="checkbox" checked={t.completed} onChange={() => dispatch({ type: 'TOGGLE', id: t.id })} />
            <span style={{ textDecoration: t.completed ? 'line-through' : 'none' }}>{t.text}</span>
            <button onClick={() => dispatch({ type: 'DELETE', id: t.id })}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default TodoApp;

import { Request, Response, NextFunction } from 'express';

interface AuthRequest extends Request {
  apiKey?: string;
}

function authMiddleware(validKeys: string[] = []): (req: AuthRequest, res: Response, next: NextFunction) => void {
  return (req: AuthRequest, res: Response, next: NextFunction): void => {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      res.status(401).json({ error: 'Missing or invalid Authorization header' });
      return;
    }
    const key = authHeader.slice(7);
    if (!validKeys.includes(key)) {
      res.status(401).json({ error: 'Invalid API key' });
      return;
    }
    req.apiKey = key;
    next();
  };
}

export { authMiddleware, AuthRequest };

// Generic debounce utility — works with any function signature
type Fn<T extends unknown[]> = (...args: T) => void;

interface DebounceOptions {
  leading?: boolean;
  trailing?: boolean;
}

function debounce<T extends unknown[]>(
  fn: Fn<T>,
  delayMs: number,
  options: DebounceOptions = {},
): Fn<T> & { cancel: () => void } {
  const { leading = false, trailing = true } = options;
  let timer: ReturnType<typeof setTimeout> | null = null;
  let lastArgs: T | null = null;

  const cancel = (): void => {
    if (timer !== null) { clearTimeout(timer); timer = null; lastArgs = null; }
  };

  const debounced = (...args: T): void => {
    lastArgs = args;
    if (leading && timer === null) {
      fn(...args);
    }
    if (timer !== null) clearTimeout(timer);
    timer = setTimeout(() => {
      if (trailing && lastArgs) fn(...lastArgs);
      timer = null;
      lastArgs = null;
    }, delayMs);
  };

  debounced.cancel = cancel;
  return debounced;
}

export { debounce };
